Ext.define('bcp.view.FileUploadFormViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.fileuploadform',

    onCategoryChange: function (field, newValue, oldValue, eOpts) {
        if (newValue && newValue === 3) {
            this.lookupReference('cateDesc').show();
        } else {
            this.lookupReference('cateDesc').hide();
        }
    },

    onFilefieldChange: function (filefield, value, eOpts) {
        if (value !== '') {
            var newValue = value.replace(/(^.*(\\|\/))?/, '');
            var v = new RegExp(
                '.(jpg|gif|doc|docx|pdf|txt|xls|xlsx|csv)$',
                'i'
            );
            var sizeInMB =
                filefield.fileInputEl.dom.files[0].size / (1024 * 1024);

            if (!v.test(newValue)) {
                Ext.Msg.alert(
                    'Validation Error ',
                    'The file type is not allowed.'
                );
                filefield.reset();
                return;
            }
            if (newValue.length > 200) {
                Ext.Msg.alert(
                    'Validation Error ',
                    'The file name cannot be greater than 200 chars.'
                );
                filefield.reset();
                return;
            }

            if (sizeInMB > 20) {
                Ext.Msg.alert(
                    'Validation Error ',
                    'The file size is greater than 20MB.'
                );
                filefield.reset();
                return;
            }

            filefield.setRawValue(newValue);
        }
    },

    cancel: function (button, e, eOpts) {
        this.fireViewEvent('cancelUpload', this.view.requestId);
    },

    upload: function (button, e, eOpts) {
        var refs = this.getReferences(),
            form = this.view.form,
            url = '',
            fileField = refs.fileLocation,
            me = this;

        if (form.isValid()) {
            //default for uploading shopping cart but this component is also reused for
            //upload other files by bankcard holders in the purchase view
            if (this.view.ownerCt.title === 'Upload File') {
                var requestId = this.getViewModel()
                    .get('record')
                    .get('requestId');
                url =
                    bcp.config.Runtime.getServerBaseUrl() +
                    'requests/' +
                    requestId +
                    '/attachment';
                //this.lookupReference('hfFileCateId').disable();
            }
            /*
            form.submit({
                url: url,
                waitMsg: 'Uploading your file...',
                //since the server does not return true in the wanted format, this handler won't work
                success: function (fp, o) {
                    Ext.Msg.alert('Success', 'Your File uploaded successfully.');
                    me.fireViewEvent('uploaded', this.result);
                },
                failure: function (form, response) {
                    Ext.Msg.alert('Upload Failed', response.result.description);
                }
            });
            */
            //to test csrfguard locally, first enable it in web.xml, then load the app and
            //open http://localhost:8080/empbc/JavaScriptServlet in a different tab
            //and finally, add this block of code before a POST and add headers: {'OWASP_TOKEN': token_value}, in the ajax call
            /********test code block begins */
            /*var xhr = window.XMLHttpRequest ? new window.XMLHttpRequest : new window.ActiveXObject("Microsoft.XMLHTTP");
            var csrfToken = {};
            xhr.open("POST", "/empbc/JavaScriptServlet", false);
            xhr.setRequestHeader("FETCH-CSRF-TOKEN", "1");
            xhr.send(null);

            var token_pair = xhr.responseText;
            token_pair = token_pair.split(":");
            var token_name = token_pair[0];
            var token_value = token_pair[1];*/
            /********test code block ends */

            //changed to use ajax request instead of simple file submit because
            //the csrftoken cannot be added to request header with file submit

            //add a fake progress window first
            Ext.MessageBox.show({
                title: 'Uploading File',
                progressText: 'Please wait...',
                progress: true,
                closable: true
            });

            // Once the file is extracted, it will no longer be available in the field
            var fileInput = fileField.extractFileInput();
            var file = fileInput.files[0];

            //get other form data
            var jsdata = form.getValues();

            //convert file content to base64 string and put it to the data attribute in the jsdata
            bcp.util.CommonUtil.convertFileToBase64(file)
                .then(function (base64File) {
                    // This is required to remove the data url part -> data:*/*;base64,
                    var base64Data = base64File.split(',')[1];

                    jsdata.data = base64Data;

                    //add these data to jsondata
                    jsdata.name = file.name;
                    jsdata.type = file.type;

                    //make ajax call, server side code is also changed to take json instead of multiformdata
                    Ext.Ajax.request({
                        url: url,
                        method: 'POST',
                        timeout: 0,
                        //headers: {'OWASP_TOKEN': token_value},
                        scope: this,
                        jsonData: jsdata,
                        success: function (response) {
                            Ext.MessageBox.hide();
                            var jsonResp = Ext.decode(response.responseText);
                            if (jsonResp.success) {
                                Ext.Msg.alert(
                                    'Success',
                                    'Your File uploaded successfully.'
                                );
                                me.fireViewEvent('uploaded', this.result);
                            } else {
                                Ext.Msg.alert(
                                    'Failure',
                                    'Unexpected error occurred. File was not uploaded.'
                                );
                            }
                        },
                        failure: function (response) {
                            Ext.MessageBox.hide();
                            Ext.Msg.alert(
                                'Failure',
                                'Unexpected error occurred. File was not uploaded.'
                            );
                            return;
                        }
                    });
                })
                .catch(function () {
                    //in case file read has a problem
                    Ext.MessageBox.hide();
                    Ext.Msg.alert(
                        'Failure',
                        'Unexpected error occurred. File was not uploaded.'
                    );
                });
        }
    },

    onFormShow: function (component, eOpts) {
        var refs = this.getReferences(),
            formPanel = refs.form,
            form = formPanel.getForm(),
            model = this.getViewModel(),
            record = model.get('record');
        // Clear form
        form.reset();
        // Set record
        form.loadRecord(record);
    }
});
